# 仅用于 DSH Windows 沙箱内跑 fast_gate 的环境垫片：
# Python 3.13 的 tempfile.mkdtemp() 会以 0700 建目录，沙箱受限令牌下连创建者
# 都无法写入/删除，导致与本次修复无关的用例 PermissionError。
# 这里只把 0700 降级为 0777，不改任何项目文件。
import os as _os

_orig_mkdir = _os.mkdir


def _mkdir(path, mode=0o777, *, dir_fd=None):
    if mode == 0o700:
        mode = 0o777
    if dir_fd is not None:
        return _orig_mkdir(path, mode, dir_fd=dir_fd)
    return _orig_mkdir(path, mode)


_os.mkdir = _mkdir
